import{z as n,x as s,o as E,c as p,q as t,j as r,D as e,d as l,s as A,S as i}from"./chunks/framework.C8m1ZpeB.js";const F=JSON.parse('{"title":"自由电子激光 EUV 源","description":"","frontmatter":{"title":"自由电子激光 EUV 源","date":"2026-09-08T00:00:00.000Z","section":"litho"},"headers":[],"relativePath":"litho/fel-euv-source.md","filePath":"litho/fel-euv-source.md","lastUpdated":1791063341000}'),d={name:"litho/fel-euv-source.md"};function B(h,a,u,P,_,m){const o=s("Mermaid");return E(),p("div",null,[a[2]||(a[2]=t('<h1 id="自由电子激光-euv-源" tabindex="-1">自由电子激光 EUV 源 <a class="header-anchor" href="#自由电子激光-euv-源" aria-label="Permalink to &quot;自由电子激光 EUV 源&quot;">​</a></h1><div class="epigraph"><p>FEL 能在 13.5 nm 给出高平均功率的设想长期存在；工业扫描机仍绑在锡 LPP 上，因为源必须与 etendue、剂量稳定和厂务一起交货。</p><footer>—— 对照 FEL 作为 EUV 源概念与 LPP 锡源量产路径的公开讨论</footer></div><p><a href="/litho/biochip-litho">上一课</a>离开 IC。缺口是逻辑源是否只能 LPP。<a href="/litho/euv-lpp-tin">EUV LPP 锡</a> 已钉量产路径。本课钉 FEL 概念。Hyper-NA 之后的物理墙，留给最后一课<a href="/litho/post-hyper-na-limits">post-hyper-na-limits</a>。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>自由电子激光：相对论电子束在波荡器中辐射，波长可调，原则上高平均功率、窄带。吸引点：减轻锡碎片、提高功率天花板。墙：加速器规模与成本、运行、etendue 与扫描机照明匹配、时间结构（脉冲）与胶随机、厂内落地。LPP 已经与 NXE 集成、有学习曲线；FEL 是另一套设施型源。</p>',5)),(E(),r(i,null,{default:e(()=>[A(o,{id:"mermaid-13",class:"mermaid",graph:"flowchart%20LR%0A%20%20EG%5B%22%E7%94%B5%E5%AD%90%E6%9E%AA%E4%BA%A7%E7%94%9F%E7%94%B5%E5%AD%90%22%5D%20--%3E%20LINAC%5B%22%E7%9B%B4%E7%BA%BF%E5%8A%A0%E9%80%9F%E5%99%A8%E6%8A%8A%E7%94%B5%E5%AD%90%E6%8F%90%E9%80%9F%E5%88%B0%E7%9B%B8%E5%AF%B9%E8%AE%BA%E9%80%9F%E5%BA%A6%22%5D%0A%20%20LINAC%20--%3E%20UND%5B%22%E6%B3%A2%E8%8D%A1%E5%99%A8%EF%BC%9A%E4%BA%A4%E5%8F%98%E7%A3%81%E5%9C%BA%22%5D%0A%20%20UND%20--%3E%20RAD%5B%22%E7%94%B5%E5%AD%90%E6%91%86%E5%8A%A8%E5%B9%B6%E8%BE%90%E5%B0%84%E7%9B%B8%E5%B9%B2%E5%85%89%22%5D%0A%20%20RAD%20--%3E%20MONO%5B%22%E5%85%89%E8%B0%B1%E7%BA%AF%E5%8C%96%E5%BE%97%E5%88%B0%E7%AA%84%E5%B8%A6%2013.5%20nm%22%5D%0A%20%20MONO%20--%3E%20ILL%5B%22%E9%80%81%E5%85%A5%E6%89%AB%E6%8F%8F%E6%9C%BA%E7%85%A7%E6%98%8E%E5%85%89%E5%AD%A6%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[l(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=t('<p>这张图回答的问题是：FEL 怎么把「电」一步步变成扫描机能用的 13.5 nm 光。链条上任何一环（尤其是加速器规模和末端与照明光学的匹配）掉链子，源就交不了货。</p><p><span class="marginnote">波荡器（undulator）就是一排磁极方向交替排列的磁铁：电子穿过时被磁场左右搓动，每摆一次甩出一小段光，这些光同相位叠加成相干辐射。波长由电子速度和磁铁周期共同决定，所以「调波长」其实是调电子能量——这也是 FEL 不必绑死在 13.5 nm 的原因。</span></p><p>缺口是<strong>源必须是可交货模块</strong>，不是光谱更漂亮就赢。把 FEL 当「LPP 之后必然」，忽略加速器工业与扫描机光学合同。</p><h3 id="与单一来源" tabindex="-1">与单一来源 <a class="header-anchor" href="#与单一来源" aria-label="Permalink to &quot;与单一来源&quot;">​</a></h3><p>FEL 若成功，可能改变源集中格局，但扫描机光学仍集中。供应链课的结构不会自动消失。</p><p><span class="marginnote">同步辐射束线做过 EUV 研究曝光，那是实验站，不是 300 wph 工厂源。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>评估：功率、dose 稳定性、etendue、占地、可用性、碎片。对照 LPP 的已知耗材（锡、collector）。研究项目可引用公开 FEL-EUV 设想，不把未建装置当量产。</p><p><span class="marginnote">etendue 可以粗译成「光的体积守恒」：光源的大小乘以发光立体角，这个乘积在光学系统里不会变小。初学者容易以为源的功率高就行——实际上扫描机只收得下固定立体角内、固定大小的光，etendue 不匹配时多出来的光子根本进不了照明系统，功率数字再漂亮也白搭。</span></p><h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>LPP 把激光能量耦合进锡等离子体；FEL 把电子束能量耦合进辐射。后者效率与束品质绑定，设施像光源实验室。扫描机要的是进入照明器的可用光子，不是源点的峰值亮度 alone。</p><p><span class="marginnote">为什么时间结构重要：光刻胶响应的是落在单位面积上的累计光子数，但脉冲间隔太长时，每个「子脉冲」相当于一次独立的小曝光，散粒噪声导致的线宽随机会随之变化。换源不只是换功率等级，剂量控制的时间形状也要跟着重新设计。</span></p>',12)),(E(),r(i,null,{default:e(()=>[A(o,{id:"mermaid-50",class:"mermaid",graph:"flowchart%20TD%0A%20%20LPP%5B%22%E9%94%A1%20LPP%3A%20%E5%B7%B2%E9%9B%86%E6%88%90%22%5D%20--%3E%20NXE%5B%22%E9%87%8F%E4%BA%A7%E6%89%AB%E6%8F%8F%E6%9C%BA%22%5D%0A%20%20FEL%5B%22FEL%20%E6%A6%82%E5%BF%B5%22%5D%20--%3E%20FAC%5B%22%E5%8A%A0%E9%80%9F%E5%99%A8%E8%AE%BE%E6%96%BD%E5%A2%99%22%5D%0A%20%20FEL%20--%3E%20MATCH%5B%22etendue%20%2F%20%E7%A8%B3%E5%AE%9A%20%2F%20%E5%8E%82%E5%8A%A1%22%5D%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[l(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=t('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不预测 FEL 取代年份。不发明装置功率数字。不贬低研究价值。</p><p>后课默认：量产源仍是 LPP 合同；下一课在投影光学与随机的物理极限上问 Hyper-NA 之后还剩什么。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>FEL 是高功率 EUV 源概念，尚未替代已集成的锡 LPP。</li><li>墙在设施、etendue 匹配与交货，不只在波长。</li><li>研究束线 ≠ 工厂源。</li><li>出处：FEL-EUV 概念与 LPP 量产路径的公开讨论。</li></ul>',5))])}const L=n(d,[["render",B]]);export{F as __pageData,L as default};
